-- LF ACT-0001 / verified semantic-misroute and pre-write authority gaps -> canonical EKB.
-- Authority: ACT-0001 / ACTUALIZACION_DB_LF -> Migration Merge Train (one migration PR).
-- Scope: ONLY two NEW EKB rows, no update of existing rows; no Router/runtime/contract mutation.
-- Source proof: github://cristhianlujan/claude-persona-lf-patch/pull/2774
-- Explicit positive-then-rollback and negative no-residue check before durable insert.
BEGIN;
DO $preflight$
DECLARE n integer;
BEGIN
  SELECT count(*) INTO n FROM public.lf_error_knowledge WHERE codigo IN ('LF-ROUTER-ACT0001-LEXICAL-MISROUTE-20261015-001','LF-ROUTER-ACT0001-PREWRITE-INTENT-GATE-20261015-002');
  IF n <> 0 THEN RAISE EXCEPTION 'LF_ROUTER_EKB_PREEXISTING_CODES_RECONCILE:%',n; END IF;
END $preflight$;
SAVEPOINT lf_router_ekb_candidate_probe;
INSERT INTO public.lf_error_knowledge (codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,lote_origen,estado,source_ref,lifecycle_phase,consumer_role,root_cause_family,detectability,source_context,evidencia)
select codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,lote_origen,estado,source_ref,lifecycle_phase,consumer_role,root_cause_family,detectability,source_context,evidencia
from jsonb_to_recordset($router_ekb_data$[{"codigo":"LF-ROUTER-ACT0001-LEXICAL-MISROUTE-20261015-001","categoria":"ROUTER_GOVERNANCE","titulo":"ACT-0001 autorizo ADAPTER_UPDATE para una solicitud de copiar texto del login B2B","descripcion":"Solicitud observada: Cambiar unicamente el texto del boton principal de la pantalla Iniciar sesion B2B a Acceder, sin modificar autenticacion ni validaciones. El Router resolvio READY_TO_EXECUTE, asset_type ADAPTER, action_code ADAPTER_UPDATE, operation_code ACTUALIZACION_ADAPTER_LF y activo ADAPTER-LF-SHELL-PROFILE-20260827. La pantalla autentica es lf_ops.pantallas codigo B2B-AUTH-001, activa, pero el registro de rutas ACT-0001 no tiene PANTALLA/SCREEN activos. No se modifico la pantalla.","causa_raiz":"public.lf_router_resolve_v1 clasifica solicitud y activo mediante coincidencias lexicales y puntuacion de catalogo. La palabra modificar pertenece a la restriccion negativa sin modificar autenticacion, pero satisface el patron regex UPDATE. El tipo PANTALLA no se reconoce en la inferencia y la busqueda prioriza un ADAPTER ajeno; no hay comprobacion semantica entre la intencion, la identidad de pantalla y la operacion antes del resultado READY_TO_EXECUTE. No esta probado que la optimizacion compacta haya eliminado una semantica previa.","patron":"PALABRA_CLAVE_NEGADA + TIPO_NO_RESUELTO + RUTA_AJENA_READY_TO_EXECUTE","prevencion":"Conservar determinismo para autoridad, acciones y contratos; cuando los datos gobernados no basten para interpretar intencion, acotar brecha semantica y resolver mediante capacidad versionada. Vincular texto SHA-256, activo canonicamente hidratado, accion y alcance positivo/negativo; bloquear READY_TO_EXECUTE si la coherencia falla o no existe ruta autorizada. Reutilizar lf_ops.pantallas y no inventar una operacion SCREEN ni otro Router.","validacion":"Repetir exactamente solicitud y variantes semanticamente equivalentes; comprobar que no se autoriza ADAPTER_UPDATE, que negaciones y restricciones se preservan, que ausencia de ruta PANTALLA bloquea de manera explicita y que casos validos existentes siguen resolviendo. Prueba negativa previa al efecto y readback del Router vivo con revision fija de catalogo/contrato. PR candidato #2774: 20/20 casos locales PASS, NO prueba de activacion.","severidad":"High","lote_origen":"ACT-0001-SEMANTIC-DETERMINISTIC-20261015","estado":"ACTIVO","source_ref":"github://cristhianlujan/claude-persona-lf-patch/pull/2774|supabase://public.lf_router_resolve_v1|supabase://lf_ops.pantallas/B2B-AUTH-001","lifecycle_phase":"router_resolution","consumer_role":["ACT-0001","ROUTER_CONSUMER"],"root_cause_family":"R2_NO_VE","detectability":"SILENT","source_context":"ROUTER-ACT0001 / 2026-10-15 / B2B-AUTH-001 / REQUEST_ORIGINAL_NEGATION / ROUTE_WRONG_ADAPTER","evidencia":"2026-10-15 read-only SQL: raw router response status READY_TO_EXECUTE, asset_type ADAPTER, action_code ADAPTER_UPDATE, operation_code ACTUALIZACION_ADAPTER_LF, downstream_execution_allowed true. lf_ops.pantallas id 51 codigo B2B-AUTH-001 nombre Iniciar sesion estado CANDIDATO activa true. lf_router_action_registry PANTALLA/SCREEN status ACTIVE count 0. PR #2774 detached validator blocks mismatch locally; no DB/production patch."},{"codigo":"LF-ROUTER-ACT0001-PREWRITE-INTENT-GATE-20261015-002","categoria":"ROUTER_GOVERNANCE","titulo":"Router y operacion ADAPTER permiten llegar a escritura antes de verificar intencion original","descripcion":"El contrato activo ACTUALIZACION_ADAPTER_LF ejecuta router orden 10, pre_write_execution_binding_gate orden 60, github_write orden 70 y semantic_judge orden 100. El control orden 60 exige execution_id, target_code, target_path, write_plan y pre_write_gate_passed, pero no origen SHA-256, alcance negado ni recibo semantico validado. El juez existente llega despues de github_write. ROUTER_DOWNSTREAM_AUTHORITY consumers_known contiene solo ACTUALIZACION_DB_LF.","causa_raiz":"La cadena de admision operacional verifica coincidencia de operacion/codigo y autorizacion de ejecucion, pero no ata el recibo de Router a la intencion textual ni comprueba sus negaciones antes del primer efecto. lf_router_downstream_authority_build_v1 reconsulta una solicitud tecnica canonical authority bind action type, que no demuestra fidelidad a la solicitud original. La capacidad downstream no cubre ACTUALIZACION_ADAPTER_LF. El juez semantico del contrato llega despues de github_write.","patron":"ROUTE_RECEIPT_WITHOUT_ORIGINAL_REQUEST_BINDING + POSTWRITE_SEMANTIC_JUDGE","prevencion":"Aprovechar el checkpoint existente pre_write_execution_binding_gate, no otro motor. Exigir y verificar request_sha256, decision semantica atestada cuando exista brecha no derivable, codigo de activo/accion/operacion actuales, scopes permitidos/prohibidos, currentness de contrato y recibo Router. Bloquear cualquier incoherencia antes de github_write. No ampliar a ciegas ROUTER_DOWNSTREAM_AUTHORITY a otros consumidores y conservar el juez pos-escritura para resultado.","validacion":"Demostrar en transaccion ROLLBACK: caso B2B original BLOCKED antes de cualquier escritura, intento sin atestacion BLOCKED, restriccion negada detectada y positivo de operacion canonicamente valida PASS del guard sin permiso autonomo de ejecucion. Confirmar mismo request SHA-256 en autorizacion downstream, checks de currentness, sin bypass de contratos existentes; verificar por Train Git=ledger=DB y readback. Aun no aplicado.","severidad":"High","lote_origen":"ACT-0001-SEMANTIC-DETERMINISTIC-20261015","estado":"ACTIVO","source_ref":"github://cristhianlujan/claude-persona-lf-patch/pull/2774|supabase://public.lf_operation_step_contracts/ACTUALIZACION_ADAPTER_LF|supabase://public.lf_router_downstream_authority_build_v1","lifecycle_phase":"pre_write_admission","consumer_role":["ACTUALIZACION_ADAPTER_LF","ACT-0001"],"root_cause_family":"R5_EROSION_PROCESO","detectability":"PROCESS_DEPENDENT","source_context":"ROUTER-ACT0001 / 2026-10-15 / ADAPTER-UPDATE-CHECKPOINT-60-70-100 / DB_READ_ONLY","evidencia":"2026-10-15 read-only SQL: active steps router seq10, pre_write_execution_binding_gate seq60 required_evidence_keys=[execution_id,target_code,target_path,write_plan,pre_write_gate_passed], github_write seq70, semantic_judge seq100. public.lf_activos ROUTER_DOWNSTREAM_AUTHORITY consumers_known=[ACTUALIZACION_DB_LF]. public.lf_router_downstream_authority_build_v1 has no request SHA in v_core, reissues synthetic Router query. No DB modification made."}]$router_ekb_data$::jsonb)
as v(codigo text,categoria text,titulo text,descripcion text,causa_raiz text,patron text,prevencion text,validacion text,severidad text,lote_origen text,estado text,source_ref text,lifecycle_phase text,consumer_role text[],root_cause_family text,detectability text,source_context text,evidencia text);
DO $positive$
DECLARE n integer;
BEGIN
  SELECT count(*) INTO n FROM public.lf_error_knowledge
  WHERE codigo IN ('LF-ROUTER-ACT0001-LEXICAL-MISROUTE-20261015-001','LF-ROUTER-ACT0001-PREWRITE-INTENT-GATE-20261015-002') AND estado='ACTIVO'
    AND (codigo<>'LF-ROUTER-ACT0001-LEXICAL-MISROUTE-20261015-001' OR (root_cause_family='R2_NO_VE' AND detectability='SILENT'))
    AND (codigo<>'LF-ROUTER-ACT0001-PREWRITE-INTENT-GATE-20261015-002' OR (root_cause_family='R5_EROSION_PROCESO' AND detectability='PROCESS_DEPENDENT'));
  IF n <> 2 THEN RAISE EXCEPTION 'LF_ROUTER_EKB_ROLLBACK_POSITIVE_FAIL:%',n; END IF;
END $positive$;
ROLLBACK TO SAVEPOINT lf_router_ekb_candidate_probe;
DO $negative$
BEGIN
  IF EXISTS(SELECT 1 FROM public.lf_error_knowledge WHERE codigo IN ('LF-ROUTER-ACT0001-LEXICAL-MISROUTE-20261015-001','LF-ROUTER-ACT0001-PREWRITE-INTENT-GATE-20261015-002'))
  THEN RAISE EXCEPTION 'LF_ROUTER_EKB_ROLLBACK_RESIDUE'; END IF;
END $negative$;
RELEASE SAVEPOINT lf_router_ekb_candidate_probe;
-- Durable insert only after rollback proof and no-residue check.
INSERT INTO public.lf_error_knowledge (codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,lote_origen,estado,source_ref,lifecycle_phase,consumer_role,root_cause_family,detectability,source_context,evidencia)
