AD_ONLY","evidencia":"2026-10-15 read-only SQL: active steps router seq10, pre_write_execution_binding_gate seq60 required_evidence_keys=[execution_id,target_code,target_path,write_plan,pre_write_gate_passed], github_write seq70, semantic_judge seq100. public.lf_activos ROUTER_DOWNSTREAM_AUTHORITY consumers_known=[ACTUALIZACION_DB_LF]. public.lf_router_downstream_authority_build_v1 has no request SHA in v_core, reissues synthetic Router query. No DB modification made."}]$router_ekb_data$::jsonb)
as v(codigo text,categoria text,titulo text,descripcion text,causa_raiz text,patron text,prevencion text,validacion text,severidad text,lote_origen text,estado text,source_ref text,lifecycle_phase text,consumer_role text[],root_cause_family text,detectability text,source_context text,evidencia text);
DO $readback$
DECLARE n integer;
BEGIN
  SELECT count(*) INTO n FROM public.lf_error_knowledge WHERE codigo IN ('LF-ROUTER-ACT0001-LEXICAL-MISROUTE-20261015-001','LF-ROUTER-ACT0001-PREWRITE-INTENT-GATE-20261015-002')
    AND estado='ACTIVO' AND source_ref LIKE '%/pull/2774%';
  IF n<>2 THEN RAISE EXCEPTION 'LF_ROUTER_EKB_DURABLE_READBACK_FAIL:%',n; END IF;
  IF (SELECT count(DISTINCT codigo) FROM public.lf_error_knowledge WHERE codigo IN ('LF-ROUTER-ACT0001-LEXICAL-MISROUTE-20261015-001','LF-ROUTER-ACT0001-PREWRITE-INTENT-GATE-20261015-002'))<>2
  THEN RAISE EXCEPTION 'LF_ROUTER_EKB_CODE_UNIQUENESS_FAIL'; END IF;
END $readback$;
COMMIT;
